import 'dart:io' show Platform;

import 'package:flutter/foundation.dart' show kIsWeb;
import 'package:flutter/services.dart';
import 'package:path_provider_platform_interface/path_provider_platform_interface.dart';

/// Application directories, answered by this app's own Android channel.
///
/// `path_provider_android` resolves its paths through `package:jni`, and the
/// current releases are incompatible: its bindings were generated by jnigen
/// 0.16 and only define a JNI type *signature*, while jni 1.2.0 resolves a
/// type's class as `className ?? signature`. Nothing supplies `className`, so
/// the first cast asks the JVM for a class literally named
/// `Landroid/content/Context;` and throws `ClassNotFoundException`
/// (`Didn't find class "Landroid/content/Context;"`). Both packages are already
/// the latest published versions, so no upgrade fixes it.
///
/// Rather than pin or fork either package, the app answers its own paths. The
/// directories are the same ones `path_provider_android` returned, so existing
/// databases and caches stay where they are, and installing this as
/// [PathProviderPlatform.instance] keeps every other consumer — `just_audio`'s
/// asset cache, `audio_service`'s cache manager — off that bridge too.
class LjodPathProvider extends PathProviderPlatform {
  LjodPathProvider();

  static const String channelName = 'dev.vz.ljod/paths';
  static const MethodChannel _channel = MethodChannel(channelName);

  static Future<String?> _path(String method) =>
      _channel.invokeMethod<String>(method);

  @override
  Future<String?> getTemporaryPath() => _path('temporary');

  @override
  Future<String?> getApplicationSupportPath() => _path('support');

  @override
  Future<String?> getApplicationDocumentsPath() => _path('documents');

  @override
  Future<String?> getApplicationCachePath() => _path('cache');

  @override
  Future<String?> getExternalStoragePath() => _path('externalStorage');

  @override
  Future<List<String>?> getExternalCachePaths() =>
      _channel.invokeListMethod<String>('externalCachePaths');

  @override
  Future<List<String>?> getExternalStoragePaths({StorageDirectory? type}) =>
      _channel.invokeListMethod<String>('externalStoragePaths', {
        'type': type?.name,
      });

  @override
  Future<String?> getDownloadsPath() => _path('downloads');
}

/// Points [PathProviderPlatform] at [LjodPathProvider] on Android.
///
/// Must run after `WidgetsFlutterBinding.ensureInitialized()`, because the Dart
/// plugin registrant installs the Android implementation there, and before
/// anything reads a directory. Other platforms keep their own implementation.
void installAppPaths() {
  if (kIsWeb || !Platform.isAndroid) return;
  PathProviderPlatform.instance = LjodPathProvider();
}
